def add_root_to_paths(paths):
    if not paths:
        return paths
    if isinstance(paths, str):
        paths = {paths}
    else:
        paths = set(paths)

    result = set()
    for path in paths:
        if path.startswith('root'):
            result.add(path)
        elif path.startswith('['):
            result.add('root' + path)
        else:
            result.add("root['{}']".format(path))
    return result
